function link(id,cb){
  var r=$id(id), n=$id(id+'-n');
  if(!r) return null;
  r.addEventListener('input',function(){ if(n) n.value=r.value; cb(); });
  if(n) n.addEventListener('change',function(){
    var v=parseFloat(n.value);
    if(isNaN(v)) v=parseFloat(r.value);
    v=clamp(v,parseFloat(r.min),parseFloat(r.max));
    n.value=v; r.value=v; cb();
  });
  return r;
}
